```javascript
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

// Création d'un nouveau client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au serveur Discord
client.once('ready', () => {
  console.log('Le bot est prêt !');
});

// Commande "bannir"
const banCommand = new SlashCommandBuilder()
  .setName('bannir')
  .setDescription('Bannir un utilisateur du serveur')
  .addUserOption((option) =>
    option
      .setName('utilisateur')
      .setDescription('Utilisateur à bannir')
      .setRequired(true)
  )
  .toJSON();

// Ajout de la commande au client
client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  if (interaction.commandName === 'bannir') {
    const user = interaction.options.getUser('utilisateur');

    // Vérification si l'utilisateur cible est dans le serveur
    if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Je n\'ai pas la permission de bannir les utilisateurs !',
        ephemeral: true,
      });
    }

    if (!interaction.guild.members.me.permissions.has('KICK_MEMBERS')) {
      return interaction.reply({
        content: 'Je n\'ai pas la permission de kick les utilisateurs !',
        ephemeral: true,
      });
    }

    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n\'avez pas la permission de bannir les utilisateurs !',
        ephemeral: true,
      });
    }

    // Bannissement de l'utilisateur cible
    try {
      await interaction.guild.members.ban(user, { days: 7, reason: 'Commande bannir' });
      return interaction.reply({ content: `L'utilisateur ${user.tag} a été banni du serveur.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({
        content: 'Une erreur est survenue lors du bannissement de l\'utilisateur.',
        ephemeral: true,
      });
    }
  }
});

// Connexion du client au serveur Discord
client.login(process.env.TOKEN);
```

N'oubliez pas de remplacer `process.env.TOKEN` par votre propre clé d'API Discord. 

