Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToSearch; // mot à rechercher
    int count = 0; // compteur d'occurrences

    // demander l'entrée du mot à rechercher
    cout << "Entrer le mot à rechercher: ";
    cin >> wordToSearch;

    // ouvrir le fichier texte
    ifstream inputFile;
    inputFile.open("input.txt");

    // vérifier si le fichier a bien été ouvert
    if (!inputFile) {
        cout << "Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // lire le fichier ligne par ligne
    string line;
    while (getline(inputFile, line)) {
        // convertir la ligne en petit majuscule pour une comparaison case-insensitive
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // chercher le mot dans la ligne
        size_t pos = line.find(wordToSearch);
        while (pos != string::npos) {
            count++; // incrémenter le compteur d'occurrences
            pos = line.find(wordToSearch, pos + 1); // chercher le mot suivant dans la ligne
        }
    }

    // fermer le fichier
    inputFile.close();

    // afficher le nombre d'occurrences du mot
    cout << "Le mot \"" << wordToSearch << "\" apparait " << count << " fois dans le fichier." << endl;

    return 0;
}
```

